          .where(and(
            inArray(airportDaylight.airportCode, airportCodes),
            or(eq(airportDaylight.date, todayStr), eq(airportDaylight.date, tomorrowStr)),
          ))
          .orderBy(asc(airportDaylight.date))
        : Promise.resolve([]),
    ]);

